CREATE view QSL_HAVLAH_ANBAR as  SELECT     dbo.HEAD_BACK_ANBAR.NUMBER1, dbo.HEAD_BACK_ANBAR.NUMBER, dbo.HEAD_BACK_ANBAR.DATE_N, dbo.INVO_LST.NUMBER AS INUMBER,                      dbo.HEAD_BACK_ANBAR.HTAG, dbo.INVO_LST.ANBAR, dbo.INVO_LST.RADIF, dbo.INVO_LST.CODE, dbo.INVO_LST.MEGH, dbo.INVO_LST.MEGHk,                      dbo.INVO_LST.MEGH_MAR, dbo.INVO_LST.MANDAH, dbo.INVO_LST.MABL, dbo.INVO_LST.MABL_K, dbo.INVO_LST.FROM_A, dbo.INVO_LST.N_RASID,                      dbo.INVO_LST.MEGH_R, dbo.INVO_LST.RADAH, dbo.INVO_LST.SANAD_NO, dbo.INVO_LST.ANBARF, dbo.INVO_LST.VAHED_K, dbo.STUF_DEF.NAME,  dbo.TCOD_ANBAR.NAMES, dbo.TCOD_VAHEDS.NAMES AS VNAMES, dbo.HEAD_BACK_ANBAR.TAH, dbo.HEAD_BACK_ANBAR.MOLAH,  dbo.CUSTKIND.CUSTKNAME, dbo.DEPART.DEPNAME, dbo.SHIFT.SHNAME, dbo.CUST_HESAB.NAME AS HESAB, dbo.CUST_HESAB.ADDRESS,  dbo.CUST_HESAB.TEL, ISNULL(dbo.STUF_DEF.NAME, N' ') + N' ' + ISNULL(dbo.INVO_LST.MANDAH, N' ') AS KALA,  dbo.HEAD_BACK_ANBAR.CUST_NO, dbo.INVO_LST.N_KOL, dbo.INVO_LST.N_MOIN, dbo.HEAD_BACK_ANBAR.FNUMCO, dbo.CUST_HESAB.ECODE,  dbo.CUST_HESAB.PCODE, dbo.CUST_HESAB.IYALAT, dbo.CUST_HESAB.MCODEM, dbo.CUST_HESAB.CITY,  dbo.INVO_LST.MABL_K - dbo.INVO_LST.N_MOIN AS mabkbt, dbo.INVO_LST.IMBAA,  dbo.INVO_LST.MABL_K - dbo.INVO_LST.N_MOIN + dbo.INVO_LST.IMBAA AS mabkn, dbo.CUST_HESAB.CODE_E, dbo.HEAD_BACK_ANBAR.TAKHFIF,  dbo.HEAD_BACK_ANBAR.MBAA, dbo.STUF_DEF.N_FANI, dbo.HEAD_BACK_ANBAR.SADER, dbo.HEAD_BACK_ANBAR.ANBARF AS ANBARFF,  dbo.OTHER_DTL.REQUEST_NO, dbo.OTHER_DTL.BARNAMEH, dbo.OTHER_DTL.DRIVER, dbo.OTHER_DTL.DRIVER_MOB,  dbo.OTHER_DTL.CAMIUN_NUM, dbo.OTHER_DTL.MAGHSAD, dbo.OTHER_DTL.CAM_KHALY, dbo.OTHER_DTL.CAM_POOR, dbo.OTHER_DTL.TOZIH,  dbo.OTHER_DTL.CAMIUN, dbo.OTHER_DTL_SUB.CODE AS CODEG, dbo.OTHER_DTL_SUB.CAM_KHALY AS CAM_KHALYG,  dbo.OTHER_DTL_SUB.CAM_POOR AS CAM_POORG, dbo.OTHER_DTL_SUB.MEGHk AS MEGHkG, dbo.OTHER_DTL_SUB.TOZIH AS TOZIHG,  dbo.OTHER_DTL_SUB.VAZNH, STUF_DEF_1.NAME AS NAMEG, dbo.HEAD_BACK_ANBAR.SHARAYET, dbo.DEPART.DEPART, dbo.INVO_LST.TKHN,  dbo.HEAD_BACK_ANBAR.MAS, dbo.HEAD_BACK_ANBAR.HTAG AS TAG, dbo.SALA_DTL.EMZA AS EMZA1, SALA_DTL_1.EMZA AS EMZA2,  SALA_DTL_2.EMZA AS EMZA3, dbo.HEAD_BACK_ANBAR.SGN1usid, dbo.HEAD_BACK_ANBAR.sgn2usid, dbo.HEAD_BACK_ANBAR.sgn3usid, dbo.HEAD_BACK_ANBAR.SGN1, dbo.HEAD_BACK_ANBAR.sgn2, dbo.HEAD_BACK_ANBAR.sgn3  FROM         dbo.OTHER_DTL RIGHT OUTER JOIN  dbo.SHIFT RIGHT OUTER JOIN  dbo.DEPART RIGHT OUTER JOIN   dbo.INVO_LST INNER JOIN  dbo.TCOD_ANBAR ON dbo.INVO_LST.ANBAR = dbo.TCOD_ANBAR.CODE INNER JOIN  dbo.HEAD_BACK_ANBAR ON dbo.INVO_LST.NUMBER = dbo.HEAD_BACK_ANBAR.NUMBER AND  dbo.INVO_LST.TAG = dbo.HEAD_BACK_ANBAR.HTAG LEFT OUTER JOIN  dbo.SALA_DTL SALA_DTL_2 ON dbo.HEAD_BACK_ANBAR.sgn3usid = SALA_DTL_2.IDD LEFT OUTER JOIN  dbo.SALA_DTL SALA_DTL_1 ON dbo.HEAD_BACK_ANBAR.sgn2usid = SALA_DTL_1.IDD LEFT OUTER JOIN  dbo.SALA_DTL ON dbo.HEAD_BACK_ANBAR.SGN1usid = dbo.SALA_DTL.IDD LEFT OUTER JOIN  dbo.STUF_DEF STUF_DEF_1 INNER JOIN  dbo.OTHER_DTL_SUB ON STUF_DEF_1.CODE = dbo.OTHER_DTL_SUB.CODE ON dbo.INVO_LST.CODE = dbo.OTHER_DTL_SUB.CODE AND  dbo.INVO_LST.NUMBER = dbo.OTHER_DTL_SUB.NUMBER AND dbo.INVO_LST.TAG = dbo.OTHER_DTL_SUB.TAGG LEFT OUTER JOIN  dbo.CUST_HESAB ON dbo.HEAD_BACK_ANBAR.CUST_NO = dbo.CUST_HESAB.hes LEFT OUTER JOIN  dbo.TCOD_VAHEDS ON dbo.INVO_LST.VAHED_K = dbo.TCOD_VAHEDS.CODE LEFT OUTER JOIN  dbo.STUF_DEF ON dbo.INVO_LST.CODE = dbo.STUF_DEF.CODE LEFT OUTER JOIN  dbo.CUSTKIND ON dbo.HEAD_BACK_ANBAR.CUST_KIND = dbo.CUSTKIND.CUST_COD ON  dbo.DEPART.DEPATMAN = dbo.HEAD_BACK_ANBAR.DEPATMAN ON dbo.SHIFT.SHIFT_ID = dbo.HEAD_BACK_ANBAR.SHIFT ON  dbo.OTHER_DTL.NUMBER = dbo.HEAD_BACK_ANBAR.NUMBER AND dbo.OTHER_DTL.TAG = dbo.HEAD_BACK_ANBAR.HTAG
